// Yields configures the stub to yield items from an iterator.
func (s *AllShapesStubAll) Yields(items ...interfaces.Record) *AllShapesStubAll {
	s.fn = func(ctx context.Context) iter.Seq[interfaces.Record] {
		return func(yield func(interfaces.Record) bool) {
			for _, item := range items {
				if !yield(item) {
					return
				}
			}
		}
	}
	return s
}

